package com.procats.study;
import android.app.*;import android.content.*;import android.os.Build;import android.os.SystemClock;import android.provider.Settings;
public final class AlarmState {
 static final int ID=11001,REQUEST=11002;static final String FIRE="com.procats.study.TIMER_FIRE",STOP="com.procats.study.TIMER_STOP",CLOSED="com.procats.study.TIMER_CLOSED",CHANNEL="procats-countdown-v2";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("procats-alarm-v2",Context.MODE_PRIVATE);}
 static String validColor(String value,String fallback){return value!=null&&value.matches("#[0-9a-fA-F]{6}")?value:fallback;}
 static int themeColor(Context c,String name,String fallback){return android.graphics.Color.parseColor(validColor(prefs(c).getString(name,fallback),fallback));}
 static boolean exact(Context c){return Build.VERSION.SDK_INT<31||c.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
 static boolean fullScreen(Context c){return Build.VERSION.SDK_INT<34||c.getSystemService(NotificationManager.class).canUseFullScreenIntent();}
 static boolean notifications(Context c){NotificationManager m=c.getSystemService(NotificationManager.class);NotificationChannel ch=m.getNotificationChannel(CHANNEL);return m.areNotificationsEnabled()&&(ch==null||ch.getImportance()!=NotificationManager.IMPORTANCE_NONE);}
 static String bootId(Context c){try{int count=Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,-1);return count>=0?String.valueOf(count):"";}catch(RuntimeException e){return "";}}
 static long remaining(Context c){SharedPreferences p=prefs(c);return DurationDeadline.remaining(p.getLong("elapsedEnd",0),p.getString("bootId",""),p.getLong("end",0),bootId(c),SystemClock.elapsedRealtime(),System.currentTimeMillis());}
 static PendingIntent fireIntent(Context c,long end){return PendingIntent.getBroadcast(c,REQUEST,new Intent(c,AlarmReceiver.class).setAction(FIRE).putExtra("end",end),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c){SharedPreferences p=prefs(c);long end=p.getLong("end",0);if(end<=0||p.getBoolean("dismissed",false))return;long elapsedEnd=SystemClock.elapsedRealtime()+Math.max(100,remaining(c));p.edit().putLong("elapsedEnd",elapsedEnd).putString("bootId",bootId(c)).commit();AlarmManager m=c.getSystemService(AlarmManager.class);PendingIntent pi=fireIntent(c,end);m.cancel(pi);if(exact(c))m.setExactAndAllowWhileIdle(AlarmManager.ELAPSED_REALTIME_WAKEUP,elapsedEnd,pi);else m.setAndAllowWhileIdle(AlarmManager.ELAPSED_REALTIME_WAKEUP,elapsedEnd,pi);}
 static void stop(Context c){SharedPreferences p=prefs(c);p.edit().putBoolean("dismissed",true).putBoolean("ringing",false).commit();c.getSystemService(AlarmManager.class).cancel(fireIntent(c,p.getLong("end",0)));c.stopService(new Intent(c,AlarmService.class));c.getSystemService(NotificationManager.class).cancel(ID);c.sendBroadcast(new Intent(CLOSED).setPackage(c.getPackageName()));}
 static Notification notification(Context c){SharedPreferences p=prefs(c);NotificationManager manager=c.getSystemService(NotificationManager.class);NotificationChannel channel=new NotificationChannel(CHANNEL,"Procats · Sayaç / Timer",NotificationManager.IMPORTANCE_HIGH);channel.setSound(null,null);channel.enableVibration(false);channel.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);manager.createNotificationChannel(channel);
 PendingIntent close=PendingIntent.getBroadcast(c,ID,new Intent(c,AlarmReceiver.class).setAction(STOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(c,ID,new Intent(c,AlarmActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
 Notification.Builder b=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_stat_timer).setColor(themeColor(c,"accent","#65A9FF")).setContentTitle("Procats").setContentText(p.getString("message","Süre tamamlandı")).setCategory(Notification.CATEGORY_ALARM).setVisibility(Notification.VISIBILITY_PRIVATE).setOngoing(true).setContentIntent(open).setDeleteIntent(close).setOnlyAlertOnce(true).addAction(new Notification.Action.Builder(null,p.getString("close","Kapat"),close).build());if(p.getBoolean("wake",false)&&fullScreen(c))b.setFullScreenIntent(open,true);return b.build();}
 static void deliver(Context c){if(prefs(c).getBoolean("dismissed",false)||prefs(c).getBoolean("ringing",false)||!notifications(c))return;Notification n=notification(c);prefs(c).edit().putBoolean("ringing",true).commit();if("silent".equals(prefs(c).getString("mode","sound"))){c.getSystemService(NotificationManager.class).notify(ID,n);return;}try{c.startForegroundService(new Intent(c,AlarmService.class));}catch(RuntimeException e){c.getSystemService(NotificationManager.class).notify(ID,n);}}
}
